parameters.command:
cat > /tmp/plan.json << 'EOF'
{
  "ops": [
    {
      "op": "add-node",
      "id": "validatePayload",
      "type": "core.action.script",
      "definitionFile": "/tmp/script_def.json",
      "label": "Validate JSON Payload",
      "inputs": {
        "script": "const body = $vars.httpWebhookTrigger1.output;\nif (!body || typeof body !== 'object') {\n  return { valid: false, statusCode: 400, message: 'Invalid or missing JSON body' };\n}\nconst requiredFields = ['id', 'type'];\nconst missing = requiredFields.filter(f => !(f in body));\nif (missing.length > 0) {\n  return { valid: false, statusCode: 422, message: 'Missing required fields: ' + missing.join(', ') };\n}\nreturn { valid: true, statusCode: 200, message: 'Payload is valid', payload: body };"
      }
    },
    {
      "op": "add-node",
      "id": "endSuccess",
      "type": "core.control.end",
      "definitionFile": "/tmp/end_def.json",
      "label": "End",
      "outputs": "none"
    },
    {
      "op": "add-edge",
      "source": "httpWebhookTrigger1",
      "sourcePort": "output",
      "target": "validatePayload",
      "targetPort": "input"
    },
    {
      "op": "add-edge",
      "source": "validatePayload",
      "sourcePort": "success",
      "target": "endSuccess",
      "targetPort": "input"
    },
    {
      "op": "add-variable",
      "id": "statusCode",
      "direction": "out",
      "type": "number",
      "description": "HTTP status code to return"
    },
    {
      "op": "add-variable",
      "id": "responseMessage",
      "direction": "out",
      "type": "string",
      "description": "Response message"
    },
    {
      "op": "add-output-mapping",
      "endNode": "endSuccess",
      "var": "statusCode",
      "source": "=js:$vars.validatePayload.output.statusCode"
    },
    {
      "op": "add-output-mapping",
      "endNode": "endSuccess",
      "var": "responseMessage",
      "source": "=js:$vars.validatePayload.output.message"
    }
  ]
}
EOF
